"""Files quoll generates: planned first (content + what is on disk), then written after confirmation."""
from __future__ import annotations

import difflib
from dataclasses import dataclass
from pathlib import Path
from typing import List, Optional

# First comment of every generated file; a file without it was written by hand and is never overwritten silently.
MARKER = "# Generated by quoll"
HEADER = f"""{MARKER} — https://github.com/theo-mrn/Quoll
# Do not edit by hand: change quoll.toml, then run `quoll {{command}} update`.
"""


@dataclass
class PlannedFile:
    path: Path
    content: str
    existing: Optional[str]
    # Written once for the project to own (e.g. Dependabot's config): `check` ignores it.
    create_only: bool = False

    @property
    def changed(self) -> bool:
        return self.existing != self.content

    @property
    def managed(self) -> bool:
        """True when the file doesn't exist yet or was generated by quoll."""
        return self.existing is None or MARKER in self.existing

    def diff(self) -> str:
        return "".join(
            difflib.unified_diff(
                (self.existing or "").splitlines(keepends=True),
                self.content.splitlines(keepends=True),
                fromfile=f"a/{self.path}",
                tofile=f"b/{self.path}",
            )
        )


def header(command: str) -> str:
    return HEADER.format(command=command)


def planned(project_dir: Path, rel: Path, content: str, create_only: bool = False) -> PlannedFile:
    target = project_dir / rel
    return PlannedFile(rel, content, target.read_text() if target.exists() else None, create_only)


def eject(text: str, command: str) -> str:
    """`text` without quoll's header, so that quoll treats the file as hand-written from now on."""
    lines = text.splitlines(keepends=True)
    body = [line for line in lines if not line.startswith((MARKER, "# Do not edit by hand"))]
    return f"# Maintained by hand (ejected from `quoll {command}`).\n" + "".join(body)


def write(project_dir: Path, files: List[PlannedFile]) -> None:
    for f in files:
        target = project_dir / f.path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(f.content)
